?><!doctype html><html lang="es"><head><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta charset="utf-8"><title>Versiones · <?=h($c['folio'])?></title><link rel="icon" href="favicon.png"><style>body{font-family:Arial;background:#f4f5f7}.w{max-width:1000px;margin:30px auto}.card{background:#fff;border-radius:10px;padding:15px;margin:10px 0}a{display:inline-block;background:#111;color:#fff;padding:8px 11px;border-radius:7px;text-decoration:none}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #eee;text-align:left}</style><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><?php srnu_appbar('cotizaciones'); ?><div class="w"><a href="cotizaciones.php">← Cotizaciones</a> <a href="cotizador.php?id=<?=$id?>">Editar actual</a> <a href="comparar_versiones.php?id=<?=$id?>">Comparar versiones</a><h1>Versiones · <?=h($c['folio'])?></h1><div class="card"><b>Versión actual</b> · <?=h($c['updated_at'])?> · Total $<?=number_format((float)$c['total'],2)?></div><?php if(!$vs):?><div class="card">Todavía no hay versiones anteriores. Se crearán automáticamente al editar y guardar esta cotización.</div><?php else:?><table class="card"><tr><th>Versión</th><th>Fecha</th><th>Motivo</th><th>Resumen</th></tr><?php foreach($vs as $v):$d=json_decode($v['snapshot_json'],true)?:[];?><tr><td>V<?= (int)$v['version_no']?></td><td><?=h($v['created_at'])?></td><td><?=h($v['motivo'])?></td><td><?=h($d['cliente']??'')?> · <?=h($d['vehiculo']??'')?> · $<?=number_format((float)($d['total']??0),2)?> · <?=count($d['items']??[])?> concepto(s) · <a href="ver_version.php?id=<?=(int)$v['id']?>">Ver versión</a></td></tr><?php endforeach;?></table><?php endif;?></div></body></html>
